import { z } from "zod";
import { Finding, Theme } from "./finding";
import { Requirement } from "./requirement";
import { Source, SourceRecord } from "./source";

/**
 * The single envelope that flows along every workflow edge (n8n-style: one input, one output).
 * A node reads the keys it `consumes` and returns the envelope with the keys it `produces` updated.
 */
export const DATA_KEYS = ["sources", "records", "findings", "themes", "requirements"] as const;
export const DataKey = z.enum(DATA_KEYS);
export type DataKey = z.infer<typeof DataKey>;

export const PipelineData = z
  .object({
    sources: z.array(Source),
    records: z.array(SourceRecord),
    findings: z.array(Finding),
    themes: z.array(Theme),
    requirements: z.array(Requirement),
  })
  .passthrough();
export type PipelineData = z.infer<typeof PipelineData>;

export function emptyPipelineData(): PipelineData {
  return { sources: [], records: [], findings: [], themes: [], requirements: [] };
}

function mergeById<T extends { id: string }>(lists: T[][]): T[] {
  const byId = new Map<string, T>();
  for (const list of lists) for (const item of list) byId.set(item.id, item);
  return [...byId.values()];
}

/**
 * How the engine combines several incoming edges into one node input:
 * concatenate per key and de-duplicate by `id`; a later input wins (order = edge order),
 * first-seen position is kept so output order stays stable.
 */
export function mergePipelineData(...parts: PipelineData[]): PipelineData {
  return {
    ...Object.assign({}, ...parts),
    sources: mergeById(parts.map((p) => p.sources)),
    records: mergeById(parts.map((p) => p.records)),
    findings: mergeById(parts.map((p) => p.findings)),
    themes: mergeById(parts.map((p) => p.themes)),
    requirements: mergeById(parts.map((p) => p.requirements)),
  };
}

export function countPipelineData(data: PipelineData): Record<DataKey, number> {
  return {
    sources: data.sources.length,
    records: data.records.length,
    findings: data.findings.length,
    themes: data.themes.length,
    requirements: data.requirements.length,
  };
}

/**
 * Finding the meaning of columns by their header. BMW's exact formats aren't known yet, so each role
 * has English and German synonyms; matching ignores case, spaces, dashes and underscores.
 * Extend the lists when the real data arrives (WS5).
 */
export const COLUMN_SYNONYMS = {
  text: [
    "comment",
    "customerfeedback",
    "customercomment",
    "feedbacktext",
    "commenttext",
    "comments",
    "feedback",
    "verbatim",
    "text",
    "remark",
    "answer",
    "response",
    "freetext",
    "kommentar",
    "freitext",
    "anmerkung",
    "antwort",
    "bemerkung",
  ],
  id: ["id", "feedbackid", "commentid", "responseid", "caseid", "ticketid", "verbatimid"],
  market: ["market", "country", "region", "markt", "land", "marketcode", "countrycode"],
  language: ["language", "lang", "locale", "sprache"],
  model: ["model", "series", "vehicle", "modell", "baureihe"],
  derivative: ["derivative", "variant", "body", "bodystyle", "derivat", "karosserie"],
  option: [
    "option",
    "optionname",
    "equipment",
    "feature",
    "optionaltext",
    "ausstattung",
    "sonderausstattung",
    "sa",
  ],
  category: ["category", "area", "kategorie", "bereich"],
  takeRate: [
    "takerate",
    "takeratepct",
    "takeratepercent",
    "rate",
    "share",
    "einbaurate",
    "einbauquote",
    "quote",
  ],
  units: [
    "units",
    "volume",
    "sales",
    "quantity",
    "deliveries",
    "stueckzahl",
    "stückzahl",
    "menge",
    "absatz",
    "zulassungen",
  ],
  period: [
    "period",
    "year",
    "quarter",
    "month",
    "date",
    "jahr",
    "quartal",
    "monat",
    "zeitraum",
    "modelyear",
  ],
} as const;

export type ColumnRole = keyof typeof COLUMN_SYNONYMS;

const norm = (s: string) => s.toLowerCase().replace(/[\s_\-./%()]+/g, "");

/** Every column that could have `role`: exact synonym matches first, then prefix matches. */
export function findColumns(header: readonly string[], role: ColumnRole): number[] {
  const names = header.map(norm);
  const synonyms: readonly string[] = COLUMN_SYNONYMS[role];
  const exact = names.flatMap((n, i) => (synonyms.includes(n) ? [i] : []));
  const prefix = names.flatMap((n, i) =>
    !exact.includes(i) && synonyms.some((s) => s.length >= 4 && n.startsWith(s)) ? [i] : [],
  );
  return [...exact, ...prefix];
}

/** Index of the column for `role`, or -1. Exact synonym matches win over prefix matches. */
export function findColumn(header: readonly string[], role: ColumnRole): number {
  return findColumns(header, role)[0] ?? -1;
}

/**
 * Parses numbers as they appear in exports: 84, "84%", "84,5 %", "1.234" (German thousands),
 * "1,234.5". Returns null when it isn't a number.
 */
export function parseNumber(value: unknown): number | null {
  if (typeof value === "number") return Number.isFinite(value) ? value : null;
  if (typeof value !== "string") return null;
  let s = value.replace(/[%\s ]/g, "");
  if (!s) return null;
  // Thousands separators only when the number doesn't start with 0 ("0,845" is a German decimal).
  if (/^-?[1-9]\d{0,2}(\.\d{3})+(,\d+)?$/.test(s)) s = s.replace(/\./g, "").replace(",", ".");
  else if (/^-?[1-9]\d{0,2}(,\d{3})+(\.\d+)?$/.test(s)) s = s.replace(/,/g, "");
  else s = s.replace(",", ".");
  const n = Number(s);
  return /^-?\d*\.?\d+$/.test(s) && Number.isFinite(n) ? n : null;
}

