311	      </div>
312	
313	      <div className="flex-1 overflow-auto bg-panel">
314	        {currentTab === "Sources" && <SourcesTable data={data} filter={filter} />}
315	        {currentTab === "Records" && <RecordsTable data={data} filter={filter} />}
316	        {currentTab === "Findings" && <FindingsTable data={data} filter={filter} />}
317	        {currentTab === "Themes" && <ThemesTable data={data} filter={filter} />}
318	        {currentTab === "Requirements" && <RequirementsTable data={data} filter={filter} />}
319	      </div>
320	    </div>
321	  );
322	}
